import {readFile} from 'node:fs/promises';
import {validatedQuery, savedFilterInput} from '../../../shared/src/index.js';
import {query} from '../client.js';

export const SEARCH_HELP = `crew search [QUERY words ...] --org ORG [--project PROJECT] [--limit N] [--cursor CURSOR]
crew search --query 'status:active AND assignee:@me' --org ORG
crew search --query-file FILE --org ORG [--all]
crew search suggest [QUERY ...] --org ORG [--caret N]
crew search check [QUERY ...]
Search matches token prefixes in keys, titles, labels, descriptions and comments.
Quoted text matches a contiguous phrase. NOT binds before AND, then OR; use parentheses.
Fields: status:, assignee:@me|unassigned|ID, label:, project:, priority>=0..4,
created>YYYY-MM-DD, updated<YYYY-MM-DD. Comparisons support =, !=, <, <=, >, >= for dates and priority.
Search lists include total, highlights, facets and nextCursor. --all traverses every page.
Results and suggestions obey your current project access and insight:read token scope.`;
export const FILTER_HELP = `crew filter list --org ORG [--visibility personal|team|all] [--team TEAM] [--owned] [--limit N] [--cursor CURSOR]
crew filter show FILTER
crew filter create --org ORG --name NAME [--query QUERY|--query-file FILE] [--description TEXT]
                   [--visibility personal|team] [--team TEAM]
crew filter edit FILTER [--name NAME] [--query QUERY|--query-file FILE] [--description TEXT]
                        [--visibility personal|team] [--team TEAM|none] [--revision N]
crew filter run FILTER [--limit N] [--cursor CURSOR] [--all]
crew filter delete FILTER --yes
crew filter options --org ORG
Team filters require current membership in that same-organization team. Only creators edit/delete.
A personal filter is private; passing --visibility personal clears its team.
Use --revision from the previous response to reject an intervening edit.`;

function required(value, name, help) {
  if (value == null || value === '' || value === true) throw new Error('Missing ' + name + '\n' + help);
  return value;
}

async function queryInput(args, options) {
  if (options.query !== undefined && options['query-file']) throw new Error('Choose either --query or --query-file');
  let source;
  if (options['query-file']) source = await readFile(required(options['query-file'], 'query file', SEARCH_HELP), 'utf8');
  else source = options.query !== undefined ? required(options.query, 'query text', SEARCH_HELP) : args.join(' ');
  return validatedQuery(source).query;
}

export async function collectSearchPages(client, path, parameters, all = false) {
  const first = await client.get(path + query(parameters));
  if (!all || !first.nextCursor) return first;
  const items = [...first.items];
  const seen = new Set();
  let cursor = first.nextCursor;
  while (cursor) {
    if (seen.has(cursor)) throw new Error('Server repeated a search cursor; traversal stopped');
    seen.add(cursor);
    const page = await client.get(path + query({...parameters, cursor}));
    items.push(...page.items);
    cursor = page.nextCursor;
  }
  return {...first, items, nextCursor: null};
}

export async function searchCommand({args, options, client, print}) {
  if (args[0] === 'help') {print(SEARCH_HELP); return;}
  if (args[0] === 'check') {
    const source = await queryInput(args.slice(1), options);
    print({query: source, ast: validatedQuery(source).ast, valid: true});
    return;
  }
  const orgId = required(options.org, '--org organization id', SEARCH_HELP);
  if (args[0] === 'suggest') {
    const source = options.query ?? args.slice(1).join(' ');
    print(await client.get('/search/suggestions' + query({orgId, projectId: options.project, q: source, caret: options.caret})));
    return;
  }
  const source = await queryInput(args, options);
  print(await collectSearchPages(client, '/search', {orgId, projectId: options.project, q: source, limit: options.limit, cursor: options.cursor}, Boolean(options.all)));
}
searchCommand.help = SEARCH_HELP;

async function filterBody(options, {partial = false} = {}) {
  const body = {};
  const map = {org: 'orgId', name: 'name', description: 'description', visibility: 'visibility', team: 'teamId'};
  for (const [option, field] of Object.entries(map)) {
    if (Object.hasOwn(options, option)) body[field] = options[option];
  }
  if (body.teamId === 'none' || body.visibility === 'personal') body.teamId = null;
  if (options.query !== undefined || options['query-file']) body.query = await queryInput([], options);
  return savedFilterInput(body, {partial});
}

export async function filterCommand({args, options, client, print}) {
  const [action = 'list', id] = args;
  if (action === 'help') {print(FILTER_HELP); return;}
  if (action === 'list' || action === 'options') {
    const orgId = required(options.org, '--org organization id', FILTER_HELP);
    print(await client.get('/filters' + (action === 'options' ? '/options' : '') + query({orgId, visibility: options.visibility, teamId: options.team, owned: options.owned ? 'true' : undefined, limit: options.limit, cursor: options.cursor})));
    return;
  }
  if (action === 'create') {
    print(await client.post('/filters', await filterBody(options)));
    return;
  }
  required(id, 'saved filter id', FILTER_HELP);
  const path = '/filters/' + encodeURIComponent(id);
  if (action === 'show') {print(await client.get(path)); return;}
  if (action === 'run') {
    print(await collectSearchPages(client, path + '/search', {limit: options.limit, cursor: options.cursor}, Boolean(options.all)));
    return;
  }
  if (action === 'edit') {
    const body = await filterBody(options, {partial: true});
    if (!Object.keys(body).length) throw new Error('Supply at least one field to edit\n' + FILTER_HELP);
    if (options.revision !== undefined) body.expectedRevision = options.revision;
    print(await client.patch(path, body));
    return;
  }
  if (action === 'delete') {
    if (!options.yes) throw new Error('Use --yes to delete a saved filter');
    print(await client.delete(path));
    return;
  }
  throw new Error('Unknown filter action: ' + action + '\n' + FILTER_HELP);
}
filterCommand.help = FILTER_HELP;

export const insightSearchCommands = {search: searchCommand, filter: filterCommand};

import {useState} from 'preact/hooks';
import {Field, Button, Notice} from '../../components/ui.jsx';
import {filterDraft, filterPayload} from './search-state.js';
import {savedFilterInput} from '../../../../shared/src/index.js';

export function FilterForm({api, filter, orgId, teams = [], onSaved, onCancel}) {
  const [draft, setDraft] = useState(() => filterDraft(filter, orgId));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const update = (field, value) => setDraft(previous => ({...previous, [field]: value}));
  const details = error?.details ?? {};
  async function save(event) {
    event.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const payload = filterPayload(draft, filter?.revision);
      const {expectedRevision, ...validated} = payload;
      savedFilterInput(validated);
      if (draft.visibility === 'team' && !draft.teamId) throw new Error('Choose a team to share this filter');
      const result = filter?.id ? await api.patch('/filters/' + filter.id, payload) : await api.post('/filters', payload);
      onSaved(result.filter);
    } catch (failure) {setError(failure);}
    finally {setBusy(false);}
  }
  return <form className="filter-form" onSubmit={save}>
    <h2>{filter?.id ? 'Edit saved filter' : 'Save this search'}</h2>
    <Notice error={error}/>
    <Field label="Name" error={details.name} value={draft.name} required maxLength={100} onInput={event => update('name', event.currentTarget.value)}/>
    <Field label="Description" error={details.description}>
      <textarea value={draft.description} maxLength={1000} onInput={event => update('description', event.currentTarget.value)}/>
    </Field>
    <Field label="Query" error={details.query}>
      <textarea value={draft.query} maxLength={4000} onInput={event => update('query', event.currentTarget.value)} aria-label="Saved filter query"/>
    </Field>
    <Field label="Visibility" error={details.visibility}>
      <select value={draft.visibility} onChange={event => update('visibility', event.currentTarget.value)}>
        <option value="personal">Personal · only you</option>
        <option value="team">Shared with a team</option>
      </select>
    </Field>
    {draft.visibility === 'team' && <Field label="Team" error={details.teamId}>
      <select required value={draft.teamId} onChange={event => update('teamId', event.currentTarget.value)}>
        <option value="">Choose one of your teams</option>
        {teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
      </select>
      {!teams.length && <p>Join a team in this organization before sharing a filter.</p>}
    </Field>}
    <p>Every run uses the current viewer’s project access. Only the creator can edit or delete a filter.</p>
    <div className="actions"><Button busy={busy} type="submit">Save filter</Button><Button type="button" disabled={busy} onClick={onCancel}>Cancel</Button></div>
  </form>;
}

import {validatedQuery, quoteQueryValue} from '../../../../shared/src/index.js';

export function searchLocation(orgId, query, projectId = '') {
  const params = new URLSearchParams({orgId, q: query});
  if (projectId) params.set('projectId', projectId);
  return '/search?' + params;
}

export function searchRequest({orgId, query = '', projectId = '', cursor = '', limit = 25}) {
  if (!orgId) throw new Error('Choose an organization before searching');
  const parsed = validatedQuery(query);
  const params = new URLSearchParams({orgId, q: parsed.query, limit: String(limit)});
  if (projectId) params.set('projectId', projectId);
  if (cursor) params.set('cursor', cursor);
  return '/search?' + params;
}

export function appendQueryFilter(query, field, value) {
  const filter = field + ':' + quoteQueryValue(value);
  const base = query.trim();
  return base ? '(' + base + ') AND ' + filter : filter;
}

export function filterDraft(filter = {}, orgId = '') {
  return {orgId: filter.orgId ?? orgId, name: filter.name ?? '', query: filter.query ?? '',
    description: filter.description ?? '', visibility: filter.visibility ?? 'personal', teamId: filter.teamId ?? ''};
}

export function filterPayload(draft, revision) {
  const payload = {...draft, teamId: draft.visibility === 'team' ? draft.teamId || null : null};
  if (revision != null) payload.expectedRevision = revision;
  return payload;
}

export function nextSearchPage(history, cursor) {
  return [...history, cursor ?? ''];
}

export function previousSearchPage(history) {
  return history.length > 1 ? history.slice(0, -1) : [''];
}

export function errorPosition(error) {
  if (!Number.isInteger(error?.details?.offset)) return null;
  return {offset: error.details.offset, end: error.details.end,
    description: 'Line ' + error.details.line + ', column ' + error.details.column};
}
